module adder_32bit_carry_tb;
    reg  [31:0] a, b;
    reg         cin;
    wire [31:0] sum;
    wire        cout;
    integer errors = 0;
    reg [31:0] expected_sum;
    reg        expected_cout;
    reg [32:0] full;

    adder_32bit_carry uut (
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum),
        .cout(cout)
    );

    task run_test;
        input [31:0] test_a;
        input [31:0] test_b;
        input        test_cin;
        begin
            a = test_a;
            b = test_b;
            cin = test_cin;
            #10;
            full = {1'b0, test_a} + {1'b0, test_b} + test_cin;
            expected_sum  = full[31:0];
            expected_cout = full[32];
            if (sum === expected_sum && cout === expected_cout) begin
                $display(" a=%0d b=%0d cin=%0b | sum=%0d cout=%0b | PASS", test_a, test_b, test_cin, sum, cout);
            end else begin
                $display(" a=%0d b=%0d cin=%0b | sum=%0d cout=%0b (expected sum=%0d cout=%0b) | FAIL",
                          test_a, test_b, test_cin, sum, cout, expected_sum, expected_cout);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        $display("==========Testbench results==========");
        $display("=====================================");

        run_test(32'd0, 32'd0, 1'b0);
        run_test(32'hFFFFFFFF, 32'd1, 1'b0);
        run_test(32'hFFFFFFFF, 32'd0, 1'b1);
        run_test(32'h7FFFFFFF, 32'h7FFFFFFF, 1'b1);
        run_test(32'hAAAAAAAA, 32'h55555555, 1'b0);
        run_test(32'h12345678, 32'h87654321, 1'b1);
        run_test(32'hFFFFFFFF, 32'hFFFFFFFF, 1'b1);

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

