`timescale 1ns/1ps

module mac_8x8_accum_tb;
    reg clk;
    reg rst;
    reg accum_en;
    reg [7:0] a, b;
    wire [19:0] acc;
    integer errors = 0;
    reg [19:0] expected_acc;
    integer i;

    mac_8x8_accum uut (
        .clk(clk),
        .rst(rst),
        .accum_en(accum_en),
        .a(a),
        .b(b),
        .acc(acc)
    );

    initial clk = 0;
    always #5 clk = ~clk;

    initial begin
        $display("==========Testbench results==========");
        $display("=====================================");

        #100; // Wait for Vivado's global GSR reset pulse (glbl.v, ~100ns) to release before driving stimulus,
              // otherwise structurally-instantiated UNISIM primitives (e.g. DSP48E1) hold their registers forced to 0.
        rst = 1; accum_en = 0; a = 0; b = 0;
        expected_acc = 0;
        @(posedge clk); #1;

        if (acc === expected_acc)
            $display(" after reset | acc=%0d (expected %0d) | PASS", acc, expected_acc);
        else begin
            $display(" after reset | acc=%0d (expected %0d) | FAIL", acc, expected_acc);
            errors = errors + 1;
        end

        rst = 0;
        accum_en = 1;
        for (i = 0; i < 5; i = i + 1) begin
            a = i + 1;
            b = i + 2;
            @(posedge clk); #1;
            expected_acc = expected_acc + (a * b);
            if (acc === expected_acc)
                $display(" cycle %0d a=%0d b=%0d | acc=%0d (expected %0d) | PASS", i, a, b, acc, expected_acc);
            else begin
                $display(" cycle %0d a=%0d b=%0d | acc=%0d (expected %0d) | FAIL", i, a, b, acc, expected_acc);
                errors = errors + 1;
            end
        end

        accum_en = 0;
        a = 8'd50; b = 8'd50;
        @(posedge clk); #1;
        if (acc === expected_acc)
            $display(" hold | acc=%0d (expected %0d) | PASS", acc, expected_acc);
        else begin
            $display(" hold | acc=%0d (expected %0d) | FAIL", acc, expected_acc);
            errors = errors + 1;
        end

        rst = 1;
        @(posedge clk); #1;
        expected_acc = 0;
        if (acc === expected_acc)
            $display(" reset again | acc=%0d (expected %0d) | PASS", acc, expected_acc);
        else begin
            $display(" reset again | acc=%0d (expected %0d) | FAIL", acc, expected_acc);
            errors = errors + 1;
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

