    reg expected_out;
    reg [63:0] test_pattern;

    shift_reg_32_srl uut (
        .clk(clk),
        .shift_en(shift_en),
        .serial_in(serial_in),
        .serial_out(serial_out)
    );

    initial clk = 0;
    always #5 clk = ~clk;

    initial begin
        $display("==========Testbench results==========");
        $display("=====================================");

        test_pattern = 64'hA5C3F00F5A3C9669;
        ref_shreg = 32'd0;
        shift_en = 1;
        serial_in = 0;

        for (i = 0; i < 64; i = i + 1) begin
            serial_in = test_pattern[63 - i];
            @(posedge clk); #1;
            ref_shreg = {ref_shreg[30:0], serial_in};
            expected_out = ref_shreg[31];
            if (i >= 31) begin
                if (serial_out === expected_out)
                    $display(" cycle %0d serial_in=%b | serial_out=%b (expected %b) | PASS", i, serial_in, serial_out, expected_out);
                else begin
                    $display(" cycle %0d serial_in=%b | serial_out=%b (expected %b) | FAIL", i, serial_in, serial_out, expected_out);
                    errors = errors + 1;
                end
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule
